import logging
import os
from ta_ttitrace import ta_ttitrace
from ute_common_store import Store
from ute_fsmaccess import ute_fsmaccess
from contextlib import contextmanager
from ute_common_interface.scope import ScopeController
from .ttitrace import enb_ttitrace
from ta_kiss_core.method_show_type import log_method_name


class ta_kiss_enb_ttitrace(ScopeController):

    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    def __init__(self):
        self._log = logging.getLogger(__name__)
        self._log.setLevel(logging.DEBUG)
        self.store = Store()

    @log_method_name
    def setup_enb_ttitrace(self, host_ip='localhost', ssh_username='ute', ssh_password='ute', ssh_port=22,
                           ssh_prompt='$ ', stream_path=None, tracer_path=None, ip_addr='192.168.255.1', timeout=120,
                           log_path='/tmp', **kwargs):
        """Setup enb ttitrace library

        :param string host_ip:      IP address of the remote machine.
        :param ssh_username:        Username for SSH authentication valid for remote machine.
        :param ssh_password:        Password for SSH authentication valid for remote machine.
        :param ssh_port:            Port of SSH service available on remote machine.
        :param ssh_prompt:          SH prompt available after log in. Default is '$ '
        :param stream_path:         Path to directory where ttistream is located.
        :param trace_path:          Path to directory where ttitrace is located.
        :param ip_addr:             eNB IP address
        :param timeout:             Execution timeout to be used in executor
        :param log_path:            Directory for output files to be moved.
        """
        alias = kwargs.get('alias', 'enb_ttitrace')
        ta_ttitrace_obj = ta_ttitrace()
        ta_ttitrace_obj.setup_ttitrace(host_ip=host_ip, ssh_username=ssh_username,
                                       ssh_password=ssh_password, ssh_port=ssh_port,
                                       ssh_prompt=ssh_prompt, stream_path=stream_path,
                                       tracer_path=tracer_path, ip_addr=ip_addr, timeout=timeout,
                                       log_path=log_path.rstrip('/'), **kwargs)
        ttitrace = enb_ttitrace(ip_addr, host_ip)
        self.store.add({'ttitrace_setup': ttitrace, 'ttitrace_enb_ip': ip_addr, 'ttitrace_uname': ssh_username,
                        'ttitrace_pwd': ssh_password, 'ttitrace_prompt': ssh_prompt, 'ttitrace_host': host_ip,
                        'ta_tti_setup': ta_ttitrace_obj}, alias)

    @log_method_name
    def start_enb_ttitrace(self, node_type, cell_id, nb=False, **kwargs):
        """Start capturing enb ttitrace
        :param string node_type:    node type, "UL", "DL", "ALL"
        :param string cell_id:      local cell resource id, it can set as 'ALL'.Also support set as 11,13
        :param bool nb:         enable NB TTI download , default is False.

        ttiStream                     for  FDD and TDD R3
        onlineTtiStream_64            for  TDD AirScale
        cli_aatrace_utility_debian &
        remote_execute_cli_debian     for  FDD AirScale

        |

        :kwargs should be used for optional switches:
            * **ip_addr** (string)      - -n for ttiStream
                                        - -i for onlineTtiStream_64
            * **port** (string)         - -P for ttiStream / onlineTtiStream_64
                                        - -p for cli_aatrace_utility_debian
            * **task** (string)         - -t for ttiStream
            * **filesize** (string)     - -m for ttiStream / onlineTtiStream_64
            * **prefix** (string)       - -o for ttiStream / onlineTtiStream_64
            * **duration** (string)     - -u for ttiStream

        |

        """
        alias = kwargs.get('alias', 'enb_ttitrace')
        if nb:
            self._log.info("Get NB IoT core info, all core will get from MACDLTTI.")
            ret = self.store.get(alias)['ttitrace_setup'].get_nb_core_id('DL', cell_id)
            core_id = ret[0]
        if not nb and str(cell_id).upper() == 'ALL':
            ret = self.store.get(alias)['ttitrace_setup'].get_all_cell_core_id(node_type)
            core_id = ret[0]
        if not nb and str(cell_id).upper() != 'ALL':
            ret = self.store.get(alias)['ttitrace_setup'].get_core_id(node_type, cell_id)
            core_id = ret[0]
        self._log.debug(kwargs)
        self._log.debug('These core will do ttitrace download {}'.format(core_id))
        if '0000' in core_id:
            raise Exception('{} can not do ttitrace download, please check enb whether onair.'.format(core_id))
        hw_type = self._get_hw_type(alias)
        self.store.get(alias)['ttitrace_setup'].node_type_and_hw_type_in_start_ttitrace(node_type, hw_type)
        self.store.get(alias)['ta_tti_setup'].start_tti_stream(core=core_id, **kwargs)

    @log_method_name
    def stop_enb_ttitrace(self, **kwargs):
        """Stop capturing enb ttitrace

        :return list:        list of names of the created dat files
        """
        alias = kwargs.get('alias', 'enb_ttitrace')
        ttitrace_files = self.store.get(alias)['ta_tti_setup'].stop_tti_stream(**kwargs)
        ttitrace_files = self.store.get(alias)['ttitrace_setup'].update_download_file_name(ttitrace_files)
        return ttitrace_files

    @log_method_name
    def decode_enb_ttitrace(self, dat_file, output=None, nb=False, **kwargs):
        """Decode dat file using TtiTracer tool.

        :param string dat_file:    input dat file name
        :param string output:      output file name defaults to <dat_file>.csv
        :param bool nb:            enable NB TTI trace parsing
        :return string:            output file name or empty string if no txt file created
        """
        alias = kwargs.get('alias', 'enb_ttitrace')
        output = output if output is not None else '{}.csv'.format(os.path.splitext(dat_file)[0])
        return self.store.get(alias)['ta_tti_setup'].convert_dat_to_txt(dat_file=dat_file,
                                                                        output=output,
                                                                        nb=nb, **kwargs)

    @log_method_name
    def stop_and_decode_enb_ttitrace(self, nb=False, ext='csv', **kwargs):
        """Stop capturing ttitrace and automatically converts the dat files to txt
        :param bool nb:     enable NB TTI trace parsing
        :return list:       list of names of successfully converted dat files
        """
        alias = kwargs.get('alias', 'enb_ttitrace')
        ttitrace_files = self.store.get(alias)['ta_tti_setup'].stop_tti_stream_and_convert_to_txt(nb=nb, ext=ext, **kwargs)
        ttitrace_files = self.store.get(alias)['ttitrace_setup'].update_download_file_name(ttitrace_files)
        return ttitrace_files

    @log_method_name
    def get_intact_core_id(self, node_type, cell_id, **kwargs):
        """Get cell's intact core id.

        :param string node_type: node type, "UL", "DL". DO NOT support ALL
        :param string cell_id: local cell resource id, support set as 11,13 and as ALL
        :return string: intact core id.
        """
        alias = kwargs.get('alias', 'enb_ttitrace')
        return self.store.get(alias)['ttitrace_setup'].get_intact_core_id(node_type, cell_id)

    def get_platform_type(self, **kwargs):
        """return the platform of enb, it will be FSM, FSM_ARM, LionFsih, MassiveMimo.

        :return  string:  platform type
        """
        alias = kwargs.get('alias', 'enb_ttitrace')
        return self.store.get(alias)['ttitrace_setup'].get_platform_type()

    def teardown_enb_ttitrace(self, **kwargs):
        """Close and cleanup ttitrace.
        """
        alias = kwargs.get('alias', 'enb_ttitrace')
        print(self.store.get(alias))
        self.store.get(alias)['ta_tti_setup'].teardown_ttitrace(**kwargs)
        self.store.remove(alias=alias)

    def teardown_all_alias_for_enb_ttitrace(self):
        """Close and cleanup all ttitrace.
        """
        self._out_of_scope()

    def _out_of_scope(self):
        """
        """
        for key in self.store.aliases:
            self.teardown_enb_ttitrace(alias=key)

    @log_method_name
    def _get_hw_type(self, alias):
        try:
            with self._new_fsmaccess_session(alias) as fsmaccess:
                hw_ver = fsmaccess.get_enb_hw_version()
        except Exception:
            hw_ver = 'Unknown'
        return hw_ver

    @contextmanager
    def _new_fsmaccess_session(self, alias):
        fsmaccess = ute_fsmaccess()
        fsmaccess.setup_enb_fsm_access(remote_host=self.store.get(alias)['ttitrace_host'],
                                       remote_ssh_user=self.store.get(alias)['ttitrace_uname'],
                                       remote_ssh_pass=self.store.get(alias)['ttitrace_pwd'],
                                       remote_ssh_prompt=self.store.get(alias)['ttitrace_prompt'],
                                       host=self.store.get(alias)['ttitrace_enb_ip'], prompt=' >',
                                       fallback_prompt='#')
        try:
            yield fsmaccess
        finally:
            fsmaccess.teardown_enb_fsm_access()
